import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
rows=[]
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H%x1f%ci%x1f%s',f'origin/friend/{b}'],text=True)
    for line in out.splitlines():
        if not line.strip(): continue
        sha,ci,subj=line.split('\x1f',2)
        msg=subprocess.check_output(['git','show','-s','--format=%B',sha],text=True)
        if 'Friend-Message: 1' in msg:
            # extract episode and utterance
            ep=''
            for l in msg.splitlines():
                if l.startswith('Episode:'): ep=l.split(':',1)[1].strip()
            # utterance after blank? get last nonempty? We'll print first utterance line
            ut=''
            for l in msg.splitlines():
                if l.startswith(('Rachel:','Monica:','Phoebe:','Joey:','Chandler:','Ross:')): ut=l; break
            rows.append((ci,sha,b,ep,ut))
rows.sort()
for r in rows:
    if r[3]=='S07/E02':
        print(r[0], r[2], r[1][:12], '|', r[4])
